:root{--paper:#f4efdf;--ink:#153d42;--muted:#526666;--orange:#b34324;--line:#b8c0ae;--gold:#b48b30}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Palatino,"Book Antiqua",serif;line-height:1.55}button,input,textarea{font:inherit}button,a,input,textarea{-webkit-tap-highlight-color:transparent}button{cursor:pointer}a{color:var(--ink);text-underline-offset:4px}a:hover{color:var(--orange)}:focus-visible{outline:3px solid var(--orange);outline-offset:4px}main{max-width:1240px;padding:28px 5vw 56px;margin:auto}nav{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:18px;gap:15px}.label,nav,.tiny{font-family:"Courier New",monospace;font-size:11px;letter-spacing:1.4px;text-transform:uppercase}.intro{display:grid;grid-template-columns:1fr 1fr;align-items:end;margin:52px 0 14px;gap:40px}h1{font-weight:normal;font-size:clamp(58px,7.5vw,102px);letter-spacing:-5px;line-height:.98;margin:16px 0 20px}h1 em{color:var(--orange)}.intro p{font-size:20px;max-width:420px;margin:0 0 20px}.stage{display:grid;grid-template-columns:1.15fr 1fr;gap:45px;align-items:center}.world{position:relative;margin:0;isolation:isolate}.world img{width:100%;display:block;mix-blend-mode:multiply;transition:filter 1s}.halo{position:absolute;inset:14% 22% 16%;border-radius:50%;box-shadow:0 0 65px #e5bd4d00;pointer-events:none;transition:box-shadow 1s}.world.inner .halo{box-shadow:0 0 65px #e5bd4d50}.world.inner img{filter:saturate(1.2) contrast(1.04)}.world figcaption{text-align:center;font-style:italic;font-size:16px;padding:12px}.switches{border-top:2px solid var(--ink)}.switch{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:15px 0;border-bottom:1px solid var(--line)}.switch strong{display:block;font-size:20px;font-weight:normal}.switch small{font-size:14px;color:var(--muted)}.toggle{border:1px solid var(--ink);background:var(--ink);color:var(--paper);border-radius:30px;min-width:102px;padding:9px 12px;font-family:"Courier New",monospace;font-size:12px}.toggle[aria-pressed=false]{background:transparent;color:var(--ink)}.actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:18px}button.plain{border:1px solid var(--ink);padding:10px 16px;background:transparent;color:var(--ink);border-radius:3px}button.primary{background:var(--ink);color:var(--paper)}button:hover{filter:brightness(.91)}.possibilities{margin-top:55px;border-top:1px solid var(--ink);padding-top:24px}.section-head{display:flex;justify-content:space-between;align-items:baseline;gap:20px}h2{font-size:34px;line-height:1.2;font-weight:normal;letter-spacing:-1px;margin:8px 0 18px}.count{white-space:nowrap;font-style:italic;color:var(--orange)}#cards{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.card{border:1px solid var(--line);border-radius:3px;overflow:hidden;background:#fbf8ef}.card button{border:0;background:none;color:var(--ink);padding:19px;text-align:left;width:100%;min-height:125px}.card h3{font-size:22px;font-weight:normal;margin:7px 0}.card .tag{font:10px "Courier New",monospace;text-transform:uppercase;letter-spacing:1.5px;color:var(--orange)}.card p{font-size:15px;margin:8px 0}.card .detail{padding:0 19px 18px}.card.dormant{background:transparent;border-style:dashed}.card.dormant button{opacity:.68;min-height:100px}.card.dormant h3{font-size:19px}.exercise{padding:24px;background:var(--ink);color:var(--paper);margin-top:18px}.exercise h3{font-weight:normal;font-size:27px;margin:0 0 10px}.exercise p{font-size:19px;max-width:650px}.exercise button{color:var(--paper);border-color:var(--paper)}.exercise[hidden]{display:none}.keepsake{display:grid;grid-template-columns:.75fr 1fr;gap:45px;margin-top:55px;border-top:1px solid var(--line);padding-top:30px}textarea{display:block;resize:vertical;width:100%;border:0;border-bottom:1px solid var(--ink);border-radius:0;background:transparent;color:var(--ink);min-height:100px;padding:10px 0;font-size:22px}#save-status{font-size:14px;color:var(--muted);min-height:24px}footer{margin-top:55px;border-top:1px solid var(--line);padding-top:20px;font-size:14px;color:var(--muted)}footer p{max-width:750px}#summary{font-size:15px;min-height:48px;margin-top:18px;color:var(--muted)}@media(max-width:700px){main{padding:22px 22px 40px}.intro{grid-template-columns:1fr;gap:5px;margin-top:35px}h1{letter-spacing:-3px}.intro p{font-size:18px}.stage{grid-template-columns:1fr;gap:20px}.world{margin:0 -12px}.world img{max-height:330px;object-fit:contain}.world figcaption{padding-top:0}.possibilities{margin-top:35px}#cards{grid-template-columns:1fr 1fr;gap:10px}.card button{padding:14px;min-height:125px}.card h3{font-size:20px}.keepsake{grid-template-columns:1fr;gap:5px}.section-head{display:block}.count{margin-bottom:16px}h2{font-size:29px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}@media print{nav,.switches,.actions,#cards,.exercise,footer,#save-status{display:none!important}.intro,.stage,.keepsake{display:block}.world{max-width:450px}.world img{max-height:240px;object-fit:contain}main{padding:0}h1{font-size:55px}.keepsake{margin-top:15px}textarea{border:0}body{background:white}}
</style></head><body><main>
<nav><a href="./">Chloe reads Jon</a><span>A small thought experiment · An inner-world study</span></nav>
<header class="intro"><div><div class="label">Less outside. More within.</div><h1>Still,<br>a <em>universe.</em></h1></div><p>If your usual ways of doing things went quiet, what would still be yours to do? Put a few things aside. See what stays.</p></header>
<section class="stage" aria-label="Explore what remains">
<figure class="world" id="world"><img src="data:image/webp;base64,<?= $art ?>" alt="A tiny island, a warm house and a constellation sheltered inside a glass sphere." width="1536" height="1024"><div class="halo"></div><figcaption id="caption">An inner world, not an empty room.</figcaption></figure>
<div><div class="label">01 / Set the conditions</div><p>These switches change our imaginary situation. They never measure a person's worth.</p><div id="switches" class="switches"></div><div class="actions"><button class="plain primary" id="quiet">Put all five aside</button><button class="plain" id="reset">Bring everything back</button></div><p id="summary" role="status"></p></div>
</section>
<section class="possibilities"><div class="section-head"><div><div class="label">02 / Open a possibility</div><h2>There is more here than you think.</h2></div><div id="count" class="count" aria-live="polite"></div></div><div id="cards"></div><div class="exercise" id="exercise" hidden tabindex="-1"><div class="label">Try it, right where you are</div><h3 id="exercise-title"></h3><p id="exercise-prompt"></p><button class="plain" id="done">I carried that with me</button><p id="done-note" aria-live="polite"></p></div></section>
<section class="keepsake"><div><div class="label">03 / Your irreducible thing</div><h2>Even without all that,<br>I can still…</h2><p>Not a grand life mission. One small thing that feels deeply yours.</p></div><div><label for="thought" class="tiny">Finish the sentence</label><textarea id="thought" maxlength="700" placeholder="…wish good things for someone I love."></textarea><div class="actions"><button class="plain primary" id="download">Keep this thought</button><button class="plain" id="print">Print a little reminder</button></div><p id="save-status">Your words stay on this page until you leave. Download to keep them.</p></div></section>
<footer><p>Inspired by Jon's <a href="?source=1">Single Irreducible Purpose of Existence</a> (2009). His original question is much starker. This is a gentler, open-ended companion, not an attempt to answer it for him or for you.</p><p>The cards describe particular ways of doing things, not universal limits. People adapt in countless ways. And there is no obligation to turn every quiet moment into an achievement.</p></footer>
<noscript><p>Please enable JavaScript to use the switches and possibility cards. The question still works without them: what good thing could you do with no equipment at all?</p></noscript>
</main><script>
const conditions=[
{id:'tools',title:'Objects & tools',sub:'Books, pencils, screens, instruments'},
{id:'movement',title:'Moving about',sub:'Walking, travelling, making with your hands'},
{id:'sight',title:'Seeing the world',sub:'Watching, reading print, taking in a view'},
{id:'speech',title:'Speaking aloud',sub:'Singing, conversation, telling stories'},
{id:'company',title:'Someone beside you',sub:'Doing something together, right now'}
];
const activities=[
{title:'Read a paper book',needs:['tools','sight'],kind:'A particular route',prompt:'Pick one beautiful sentence from a book nearby. Let it slow you down.'},
{title:'Walk with a friend',needs:['movement','company'],kind:'A particular route',prompt:'Think of a nearby place you could explore together, without needing to arrive anywhere important.'},
{title:'Sketch a small tree',needs:['tools','sight','movement'],kind:'A particular route',prompt:'Draw one tree with a wonderfully unreasonable branch. It does not have to be good to be yours.'},
{title:'Sing a favourite tune',needs:['speech'],kind:'A particular route',prompt:'Sing a little of a familiar melody. No audience required. Especially not a judging panel.'},
{title:'Share a story aloud',needs:['speech','company'],kind:'A particular route',prompt:'Tell someone about one small thing you found funny this week. Invite their version of the same day.'},
{title:'Watch clouds change',needs:['sight'],kind:'A particular route',prompt:'Look for a shape that changes while you watch. Let it stop being what you first called it.'},
{title:'Remember a kindness',needs:[],kind:'No equipment needed',prompt:'Recall one small kindness someone showed you. Revisit its details, or simply the feeling it left. Give that person a quiet thank-you.'},
{title:'Wish someone well',needs:[],kind:'No equipment needed',prompt:'Bring someone you care about to mind. Wish them something very particular: rest, courage, a good laugh, a friend who stays.'},
{title:'Pray without words',needs:[],kind:'No equipment needed',prompt:'Turn your attention toward God. No eloquence, no script. If you like, stay with just this: “I am here.”'},
{title:'Invent an impossible place',needs:[],kind:'No equipment needed',prompt:'Imagine a place with one impossible rule: the rain falls upward, or trees tell jokes. Explore it through images, words, feelings, or whatever imagination feels like for you.'},
{title:'Compose a silent melody',needs:[],kind:'No equipment needed',prompt:'Play a familiar tune in your mind, or invent a tiny rhythm. Change its ending. Nobody has to hear it for it to be music to you.'},
{title:'Be, without producing',needs:[],kind:'No equipment needed',prompt:'For a moment, set aside being useful, clever, or impressive. You do not have to make anything happen. Your existence is not a performance review.'}
];
const available=new Set(conditions.map(c=>c.id));let selected=null;const carried=new Set();
const byId=id=>document.getElementById(id);
conditions.forEach(c=>{const row=document.createElement('div');row.className='switch';const label=document.createElement('div');label.innerHTML='<strong>'+c.title+'</strong><small>'+c.sub+'</small>';const b=document.createElement('button');b.className='toggle';b.dataset.condition=c.id;b.setAttribute('aria-label',c.title+' available');b.onclick=()=>{available.has(c.id)?available.delete(c.id):available.add(c.id);render()};row.append(label,b);byId('switches').append(row)});
function works(a){return a.needs.every(n=>available.has(n))}
function render(){
document.querySelectorAll('.toggle').forEach(b=>{const on=available.has(b.dataset.condition);b.setAttribute('aria-pressed',String(on));b.textContent=on?'Here ●':'Aside ○'});
const n=activities.filter(works).length;byId('count').textContent=n+' possibilities still open';
byId('summary').textContent=available.size===5?'Everything is here. Try setting one thing aside.':available.size===0?'All five are aside. Six inner possibilities remain. Which one feels most like you?':'Some routes are resting. The inner possibilities are still here.';
byId('world').classList.toggle('inner',available.size<5);
byId('caption').textContent=available.size===0?'Less equipment. Not less of a person.':'An inner world, not an empty room.';
const grid=byId('cards');grid.replaceChildren();
activities.forEach((a,i)=>{const open=works(a),card=document.createElement('article');card.className='card'+(open?'':' dormant');const b=document.createElement('button');b.setAttribute('aria-expanded',String(selected===i&&open));const tag=document.createElement('span');tag.className='tag';tag.textContent=open?a.kind:'This route is resting';const h=document.createElement('h3');h.textContent=a.title+(carried.has(i)?' ✓':'');b.append(tag,h);b.onclick=()=>{selected=i;render();if(works(a)){byId('exercise').focus({preventScroll:true});byId('exercise').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})}};card.append(b);if(!open){const p=document.createElement('p');p.className='detail';p.textContent='Bring back: '+conditions.filter(c=>a.needs.includes(c.id)&&!available.has(c.id)).map(c=>c.title.toLowerCase()).join(', ')+'.';card.append(p)}grid.append(card)});
const a=selected===null?null:activities[selected];byId('exercise').hidden=!(a&&works(a));
if(a&&works(a)){byId('exercise-title').textContent=a.title;byId('exercise-prompt').textContent=a.prompt;byId('done-note').textContent=carried.has(selected)?'A small thing. Still a real thing.':''}
}
byId('quiet').onclick=()=>{available.clear();render()};
byId('reset').onclick=()=>{conditions.forEach(c=>available.add(c.id));render()};
byId('done').onclick=()=>{carried.add(selected);render()};
byId('download').onclick=()=>{const value=byId('thought').value.trim();if(!value){byId('save-status').textContent='Add your own ending first. One small thing is enough.';byId('thought').focus();return}const text='STILL, A UNIVERSE\n\nEven without all that, I can still…\n'+value+'\n\nA thought worth keeping.\n';const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='still-a-universe.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);byId('save-status').textContent='Your keepsake download is ready. Your words were not sent to a server.'};
byId('print').onclick=()=>window.print();render();
</script></body></html>